import { expect, expectStatus, test } from "../../fixtures";

test("An unparseable expiry date is extracted as null with low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

  // Act
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
      { message: "processing finishes for the certificate", timeout: 30_000 },
    )
    .not.toBe("processing");

  // Assert
  const stored = await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200);
  expect(stored.status).toBe("extracted");

  const extraction = await expectStatus<{ fields: Record<string, { value: string | null; confidence: number }> }>(
    await member.get(`/api/documents/${document.id}/extraction`),
    200,
  );
  const expiry = extraction.fields.expiry_date;
  expect(expiry, "expiry_date field is present").toBeDefined();
  expect(expiry.value, "unparseable expiry date is stored as null").toBeNull();
  expect(expiry.confidence, "confidence for an unparseable field").toBeLessThan(0.5);
});
